#
# cr-1 -- RIPv2 on the management side (issue: BIRD on the router pair).
#
# The router id is this router's own management address, so the two
# peers can never share one: a duplicated router id is a real RIP
# fault, not a cosmetic one.
#
# "management" is a REAL interface name, not eth0 (ADR-0259). It used
# to be positional -- management happened to be the first entry in this
# container's networks array -- and reordering that array would have
# silently moved RIP onto the services subnet with no error anywhere.
#
# Logging goes to stderr, not syslog. These minimal images carry no
# /dev/log, so "log syslog all" would parse, start, and then write
# nowhere; capture_output is on for this container, so stderr is
# readable through GET /v1/containers/cr-1 and the log store.
#
log stderr all;

router id 192.168.15.101;

protocol device {
    scan time 10;
}

protocol kernel {
    ipv4 {
        export all;
    };
}

protocol direct  {
    ipv4;
}

protocol static {
    ipv4;
}

protocol rip {
    ipv4 {
        import all;
        export all;
    };

    interface "management" {
        version 2;
        authentication plaintext;
        password "{{SECRET:RIP_PASSWORD}}";
    };
}
